/*
 * A141573  Prime powers of pairs of the infinite list generated by the flat
 *          list of the factorizations of all integers.
 * https://oeis.org/A141573
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, less
 * Formula:   not stated
 * Range:     u8 n <= 11, u16 n <= 14, u32 n <= 20, u64 n <= 20, u128 n <= 44,
 *            big any n
 * Helpers:   big_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation of OEIS A141573:
   Generate the infinite flat list of prime factors of all positive
   integers (1 is written as 1).  Remove delimiters, pair successive
   elements, interpret the first as a base and the second as an exponent,
   and compute base^exponent.
   Indexing is 1‑based: a(1) = 1² = 1.  The function works in any order
   of calls and memoizes results. */
#include <stdint.h>
#include <stdlib.h>
#include "../utils/big_pow.h"

/*---------- Helper arrays -------------------------------------------*/
/* Smallest prime factor table */
static idx_t spf_lim = 0;
static uint64_t *spf = NULL;

static void ensure_spf(idx_t up)
/* Make spf[1..up] available */
{
    if (up <= spf_lim) return;
    uint64_t *newf = (uint64_t*)calloc((size_t)(up + 1), sizeof(uint64_t));
    if (!newf) { free(spf); spf = NULL; spf_lim = 0; return; }
    free(spf);
    spf = newf;
    spf_lim = up;
    spf[1] = 1;
    for (idx_t i = 2; i <= up; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            if (i > up / i) continue;
            for (idx_t j = i*i; j <= up; j += i)
                if (spf[j] == 0) spf[j] = i;
        }
    }
}

/* Flat list of prime factors */
static uint64_t *fact     = NULL;
static size_t   fact_cap  = 0;
static size_t   fact_len  = 0;
static idx_t    fact_ptr  = 0;
static void ensure_fact_cap(size_t needed)
{
    if (fact_cap >= needed) return;
    size_t new_cap = fact_cap ? fact_cap*2 : 128;
    while (new_cap < needed) new_cap <<= 1;
    uint64_t *f = (uint64_t*)realloc(fact, new_cap * sizeof(uint64_t));
    if (!f) return;  /* silently abort on allocation failure */
    fact = f;
    fact_cap = new_cap;
}

/* Sequence cache */
static seq_t *cache    = NULL;
static idx_t  cache_cap = 0;
static idx_t  cache_len = 0;
static void ensure_cache_cap(idx_t needed)
{
    if (cache_cap >= needed) return;
    size_t new_cap = cache_cap ? cache_cap*2 : 128;
    while (new_cap < (size_t)needed) new_cap <<= 1;
    seq_t *c = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
    if (!c) return;
    cache = c;
    cache_cap = (idx_t)new_cap;
}

/* Next integer to factorise */
static idx_t next_num = 1;

/*---------------------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0) return 0;
    /* Generate terms until we have at least n of them */
    while (cache_len < n) {
        /* Factorise next_num and append its factors to 'fact' */
        ensure_spf(next_num);
        uint64_t t = (uint64_t)next_num;
        if (t == 1) {
            ensure_fact_cap(fact_len + 1);
            fact[fact_len++] = 1;
        } else {
            while (t > 1) {
                uint64_t p = spf[t];
                ensure_fact_cap(fact_len + 1);
                fact[fact_len++] = p;
                t /= p;
            }
        }

        /* Build terms by pairing consecutive factors */
        while (fact_len - fact_ptr >= 2) {
            uint64_t base = fact[fact_ptr++];
            uint64_t exp  = fact[fact_ptr++];
            seq_t val = big_pow((seq_t)base, (seq_t)exp);
            ensure_cache_cap(cache_len + 1);
            cache[cache_len++] = val;
        }
        ++next_num;
    }
    return cache[n-1];
}
